//! 🔭️ Synchronous reborrow preserves the original receipt on completion, refusal and unwind.
use super::{NativeEncodeControl,NativeEncodeProgress};
struct Scope<'owner,'call>{control:NativeEncodeControl<'call>,maximum:&'owner mut usize,scope_maximum:&'owner mut Option<usize>,owned:&'owner mut usize,completed:&'owner mut usize,total:&'owner mut usize,started:&'owner mut bool,stage:&'owner mut u64,depth:&'owner mut usize,actual:&'owner mut u64,reserved:&'owner mut u64}
impl Drop for Scope<'_, '_>{fn drop(&mut self){*self.maximum=self.control.maximum_bytes;*self.scope_maximum=self.control.scope_maximum;*self.owned=self.control.owned_bytes;*self.completed=self.control.completed;*self.total=self.control.total;*self.started=self.control.started;*self.stage=self.control.stage;*self.depth=self.control.depth;*self.actual=self.control.action.actual;*self.reserved=self.control.action.reserved;}}
pub(super) fn run<T,E>(original:&mut NativeEncodeControl<'_>,observer:&mut dyn FnMut(NativeEncodeProgress)->bool,operation:impl FnOnce(&mut NativeEncodeControl<'_>)->Result<T,E>)->Result<T,E>{
 let has_work=original.work.is_some();
 let mut callback=|event|(*original.callback)(event)&&observer(event);
 let mut work=|units,owned|match original.work.as_mut(){Some(port)=>(**port)(units,owned),None=>Ok(())};
 let mut scoped=original.scoped_allocation.as_mut().map(|port|port.reborrow());
 let mut forwarded=match &mut original.allocation{super::allocation::Binding::Local=>None,super::allocation::Binding::Forwarded(port)=>Some(port.reborrow())};
 let control=NativeEncodeControl{scope_maximum:original.scope_maximum,retirement:original.retirement.as_deref_mut(),construction:original.construction.as_mut().map(|port|&mut **port as &mut dyn super::NativeEncodeConstructionRecipient),construction_identity:original.construction_identity,receiving:original.receiving,maximum_bytes:original.maximum_bytes,owned_bytes:original.owned_bytes,completed:original.completed,total:original.total,started:original.started,stage:original.stage,depth:original.depth,source_depth:original.source_depth,callback:&mut callback,allocation:match forwarded.as_mut(){Some(port)=>super::allocation::Binding::Forwarded(port),None=>super::allocation::Binding::Local},scoped_allocation:scoped.as_mut(),work:if has_work{Some(&mut work)}else{None},action:super::action::Action{actual:original.action.actual,baseline:original.action.baseline,reserved:original.action.reserved,identity:original.action.identity,recipient:original.action.recipient.as_mut().map(|port|&mut **port as &mut dyn super::NativeEncodeWorkRecipient)}};
 let mut scope=Scope{control,maximum:&mut original.maximum_bytes,scope_maximum:&mut original.scope_maximum,owned:&mut original.owned_bytes,completed:&mut original.completed,total:&mut original.total,started:&mut original.started,stage:&mut original.stage,depth:&mut original.depth,actual:&mut original.action.actual,reserved:&mut original.action.reserved};
 operation(&mut scope.control)
}
